package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import com.google.android.gms.tasks.Tasks;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.io.*;
public class JapaneseReadingTest extends Instrumentation {
    void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier predicate,String message)throws Exception{long until=SystemClock.elapsedRealtime()+40000;while(SystemClock.elapsedRealtime()<until){AtomicBoolean result=new AtomicBoolean();ui(()->result.set(predicate.getAsBoolean()));if(result.get())return;Thread.sleep(50);}throw new AssertionError(message);}
    void stage(String text){Bundle state=new Bundle();state.putString("stage",text);sendStatus(1,state);}
    void book(MainActivity a,String value){a.stop();a.text=value;a.chapters=MainActivity.parse(value);a.chapter=0;a.position=0;a.loopPlayback=false;a.showPosition(true);}
    void screenshot(String name)throws Exception{waitForIdleSync();Thread.sleep(300);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();MainActivity activity=null;boolean passed=false;Context context=getTargetContext();android.content.SharedPreferences prefs=context.getSharedPreferences("reading_settings",0);android.content.SharedPreferences saved=context.getSharedPreferences("japanese_test_backup",0);if(!saved.getBoolean("saved",false)){android.content.SharedPreferences.Editor snapshot=saved.edit();for(Map.Entry<String,?> e:prefs.getAll().entrySet()){Object value=e.getValue();if(value instanceof String)snapshot.putString(e.getKey(),(String)value);else if(value instanceof Integer)snapshot.putInt(e.getKey(),(Integer)value);else if(value instanceof Float)snapshot.putFloat(e.getKey(),(Float)value);else if(value instanceof Boolean)snapshot.putBoolean(e.getKey(),(Boolean)value);else if(value instanceof Long)snapshot.putLong(e.getKey(),(Long)value);}snapshot.putBoolean("saved",true).commit();}Map<String,?> backup=new HashMap<>(saved.getAll());backup.remove("saved");try{
        check(!context.getSystemService(KeyguardManager.class).isKeyguardLocked(),"Unlock phone for UI test");activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","japanese_target_qa").putExtra("book_name","日文译读验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.system.initialized&&a.offlineReady,"voices not ready");Tasks.await(a.translation.available(),20,TimeUnit.SECONDS);check(a.translation.installed.contains("ja")&&a.translation.installed.contains("zh"),"Japanese/Chinese model missing");StringBuilder inventory=new StringBuilder();for(SystemSpeaker.Option option:a.system.options)if(option.voice.getLocale().getLanguage().equals("ja"))inventory.append(option.key).append(" network=").append(option.voice.isNetworkConnectionRequired()).append(" features=").append(option.voice.getFeatures()).append('\n');result.putString("japaneseVoices",inventory.toString());
        String chinese="小马正在看书。今天阳光明媚，我们一起去公园散步。这里有很多漂亮的花朵。";String english="The little horse is reading a book. Today the weather is sunny and we are walking in the park. There are many beautiful flowers here.";String original="今日は天気がいいです。小さな馬は公園で本を読んでいます。花がとてもきれいです。";
        stage("translating Japanese text");String fromChinese=a.translation.session(Collections.singletonList(chinese),"ja").get(0),fromEnglish=a.translation.session(Collections.singletonList(english),"ja").get(0);check(fromChinese.codePoints().anyMatch(c->Character.UnicodeScript.of(c)==Character.UnicodeScript.HIRAGANA),"Chinese not translated to Japanese");check(fromEnglish.codePoints().anyMatch(c->Character.UnicodeScript.of(c)==Character.UnicodeScript.HIRAGANA),"English not translated to Japanese");check(a.translation.session(Collections.singletonList(original),"ja").get(0).equals(original),"Japanese original changed");check(TranslationText.heading("English").translated("ja").equals("英語"),"heading not Japanese");result.putString("chineseToJapanese",fromChinese);result.putString("englishToJapanese",fromEnglish);
        ui(()->{book(a,chinese);a.readingLanguage="zh";a.systemVoiceKey=a.system.offlineVoice("zh","").key;a.chooseReadingLanguage();check(a.languagePicker.choices.size()==4&&a.languagePicker.choices.containsKey("ja"),"Japanese card missing");});screenshot("reading-language-with-japanese.png");SystemSpeaker.Option japanese=a.system.offlineVoice("ja","");check(japanese!=null,"No offline Japanese TTS voice installed");
        stage("starting Chinese-to-Japanese body");ui(()->{a.languagePicker.choices.get("ja").performClick();check(a.readingLanguage.equals("ja"),"Japanese selection failed");check(a.system.find(a.systemVoiceKey).voice.getLocale().getLanguage().equals("ja"),"Japanese uses wrong voice");a.chooseReadingLanguage();check(a.languagePicker.choices.get("ja").isSelected(),"Japanese not marked selected");a.languagePicker.dismiss();a.chooseVoice();for(VoicePicker.Item item:a.voicePicker.host.items())check(item.key.startsWith("system:")&&a.system.find(item.key.substring(7)).voice.getLocale().getLanguage().equals("ja"),"incompatible voice visible");a.voicePicker.dismiss();a.startReading();});await(()->a.playing&&a.focusGeneration==a.generation&&a.translatedSession!=null&&a.latestStatus.contains(a.readingLanguageName("ja"))&&a.latestStatus.contains("Google Translate"),"Chinese-to-Japanese playback not started");ui(()->{check(a.latestHighlightStart>=0&&a.latestHighlightEnd>a.latestHighlightStart,"source highlight missing");check(a.content.getText().toString().equals(chinese),"source text replaced");stage("starting English-to-Japanese body");a.stop();book(a,english);a.startReading();});await(()->a.playing&&a.focusGeneration==a.generation&&a.translatedSession!=null&&a.latestStatus.contains(a.readingLanguageName("ja"))&&a.latestStatus.contains("Google Translate"),"English-to-Japanese playback not started");ui(()->{stage("starting original Japanese body");a.stop();book(a,original);a.startReading();});await(()->a.playing&&a.focusGeneration==a.generation&&a.translatedSession!=null&&a.latestStatus.contains(a.readingLanguageName("ja"))&&a.latestStatus.contains("Google Translate"),"Japanese original playback not started");
        ui(()->{a.stop();String key=a.systemVoiceKey;a.applyReadingLanguage("en",false);check(a.system.find(a.systemVoiceKey).voice.getLocale().getLanguage().equals("en"),"English switch failed");a.applyReadingLanguage("ja",false);check(a.systemVoiceKey.equals(key),"Japanese voice preference not restored");a.chooseVoice();VoicePicker.Item item=a.voicePicker.host.items().get(0);a.previewVoice(item);});await(()->!a.previewKey.isEmpty(),"Japanese preview did not start");ui(()->{a.voicePicker.host.preview(a.voicePicker.host.items().get(0));check(a.previewKey.isEmpty(),"Japanese preview pause failed");a.voicePicker.dismiss();a.applyReadingLanguage("zh",false);check(a.ensureReadingVoice(),"Chinese mode not restored");});result.putString("result","PASS: four language cards; Chinese/English to Japanese offline translation and actual Japanese TTS playback; Japanese original unchanged; source text/highlight; Japanese-only voice list; Japanese preview/pause; separate voice preferences; English/Chinese switching");passed=true;
    }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}android.content.SharedPreferences.Editor restore=prefs.edit().clear();for(Map.Entry<String,?> entry:backup.entrySet()){Object value=entry.getValue();String key=entry.getKey();if(value instanceof String)restore.putString(key,(String)value);else if(value instanceof Boolean)restore.putBoolean(key,(Boolean)value);else if(value instanceof Integer)restore.putInt(key,(Integer)value);else if(value instanceof Float)restore.putFloat(key,(Float)value);else if(value instanceof Long)restore.putLong(key,(Long)value);}restore.commit();saved.edit().clear().commit();context.getSharedPreferences("reader_japanese_target_qa",0).edit().clear().commit();new File(context.getFilesDir(),"book_japanese_target_qa.txt.position").delete();}finish(passed?-1:0,result);}
}
